use mill.stock;
use mill.rules;

pub fn lines() -> String {
    let planks = stock.inventory();
    var output = "";
    var first = true;

    for plank in planks {
        if rules.keep(plank) {
            if first {
                first = false;
            } else {
                output = output.concat(other: ",");
            }
            output = output.concat(other: rules.label(plank));
        }
    }

    output
}

