use harbor.signal;

pub fn entries() -> String {
    var result = "";
    var separator = "";

    for current in signal.today() {
        let rendered = match current {
            signal.Calm => "calm",
            signal.Gale(speed) => "gale:".concat(other: speed.to_text()),
            signal.Fog(density) => "fog:".concat(other: density),
        };

        result = result.concat(other: separator).concat(other: rendered);
        separator = ";";
    }

    result
}

