use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var total = 0;

    for frame in feed.frames() {
        let value = match feed.decode(frame) {
            Ok(value) => value,
            Err(_) => 0,
        };
        total = total + value;
    }

    feed.emit(io: io, total: total)?;
    return Ok(unit);
}

