import stable.herd as herd;
import stable.ledger as ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let ponies = herd.lineup();
    var output = "";
    var i = 0;

    while i < ponies.length() {
        let fed = herd.feed(pony: ponies[i], scoops: 3);
        let entry = ledger.render(fed);

        if i > 0 {
            output = output.concat(other: ",");
        }
        output = output.concat(other: entry);
        i = i + 1;
    }

    io.write(text: output)?;
    return Ok(unit);
}

